/** Pinned identity of the Chatterbox Turbo files; the manifests are generated by scripts/pin-hf-assets.mjs. */
import { CHATTERBOX_TURBO_ASSETS } from "../workers/manifests/chatterbox";
import { CHATTERBOX_DEFAULT_VOICE_ASSETS } from "../workers/manifests/chatterboxDefaultVoice";
import {
  CHATTERBOX_SESSIONS,
  chatterboxGraphPath,
  selectChatterboxAssetFiles,
  type ChatterboxDtype,
} from "./chatterboxAssets";
import type { PinnedAssetIntegrity } from "./pinnedModelFetch";

export const CHATTERBOX_MODEL_ID = CHATTERBOX_TURBO_ASSETS.repo;
export const CHATTERBOX_MODEL_REVISION = CHATTERBOX_TURBO_ASSETS.revision;

/** The ResembleAI sample clip the ONNX export ships for its default voice (not part of the Turbo repo). */
export const CHATTERBOX_DEFAULT_VOICE = {
  modelId: CHATTERBOX_DEFAULT_VOICE_ASSETS.repo,
  revision: CHATTERBOX_DEFAULT_VOICE_ASSETS.revision,
  file: "default_voice.wav",
  integrity: CHATTERBOX_DEFAULT_VOICE_ASSETS.files["default_voice.wav"] as PinnedAssetIntegrity,
};

/**
 * Every file one dtype plan loads, with its exact size and digest. A graph
 * the manifest does not pin would otherwise be refused mid-load by the asset
 * guard, so it fails here instead.
 */
export function getChatterboxAssetManifest(dtype: ChatterboxDtype): Record<string, PinnedAssetIntegrity> {
  const files = selectChatterboxAssetFiles(CHATTERBOX_TURBO_ASSETS.files, dtype);
  for (const session of CHATTERBOX_SESSIONS) {
    const graph = chatterboxGraphPath(session, dtype[session]);
    if (!Object.hasOwn(files, graph) || !Object.hasOwn(files, `${graph}_data`)) {
      throw new Error(`Chatterbox Turbo ${graph} is not part of the pinned manifest.`);
    }
  }
  return files;
}
